/* ===== mobile hot-fix (app-mobile) ===== */
:root {
  --gt-sat: env(safe-area-inset-top, 0px);
  --gt-sab: env(safe-area-inset-bottom, 0px);
  --gt-sal: env(safe-area-inset-left, 0px);
  --gt-sar: env(safe-area-inset-right, 0px);
  --gt-hdr: 52px; --gt-tabs: 45px; --gt-dock: 140px;
  --gt-maph: calc(100dvh - var(--gt-sat) - var(--gt-hdr) - var(--gt-tabs) - var(--gt-dock) - var(--gt-sab));
}
html { overscroll-behavior: none; -webkit-tap-highlight-color: transparent; }
html[data-layout="mobile"] #extra-features { display: none !important; }
.gtbg-m-root { user-select: none; -webkit-user-select: none; -webkit-touch-callout: none; }
.gtbg-m-top { padding-left: max(14px, var(--gt-sal)) !important; padding-right: max(14px, var(--gt-sar)) !important; }
.gtbg-m-dock { padding-left: var(--gt-sal); padding-right: var(--gt-sar); }
.gtbg-m-scrub { touch-action: none; }
.gtbg-m-play { gap: clamp(6px, 2.4vw, 14px) !important; padding-left: 12px !important; padding-right: 12px !important; }
.gtbg-m-play > button { flex-shrink: 0; }
/* re-homed desktop panels (search/filter/story/event/toasts) */
.gtbg-mp-top { display: contents; }
.gtbg-mp-top > div { position: fixed !important; left: max(8px, var(--gt-sal)) !important; right: max(8px, var(--gt-sar)) !important; top: calc(var(--gt-sat) + 8px) !important; bottom: auto !important; width: auto !important; max-width: none !important; transform: none !important; z-index: 450 !important; max-height: calc(100dvh - 24px - var(--gt-sat)) !important; }
.gtbg-mp-story { position: fixed; left: max(8px, var(--gt-sal)); right: max(8px, var(--gt-sar)); bottom: calc(var(--gt-dock) + var(--gt-sab) + 8px); z-index: 260; display: flex; flex-direction: column-reverse; gap: 8px; max-height: calc(var(--gt-maph) * .68); overflow-y: auto; overflow-x: hidden; overscroll-behavior: contain; pointer-events: none; }
.gtbg-mp-story > div { position: static !important; width: auto !important; max-width: none !important; transform: none !important; max-height: calc(var(--gt-maph) * .48) !important; flex: 0 0 auto; pointer-events: auto; overflow-y: auto; overflow-x: hidden; }
.gtbg-mp-toast { position: fixed; left: max(8px, var(--gt-sal)); right: max(8px, var(--gt-sar)); top: calc(var(--gt-hdr) + var(--gt-tabs) + var(--gt-sat) + 8px); z-index: 270; pointer-events: none; }
.gtbg-mp-toast > div { position: static !important; max-width: none !important; }
.gtbg-mp-story button, .gtbg-mp-top button, .gtbg-mp-toast button { min-width: 44px; min-height: 44px; }
.mapboxgl-ctrl-attrib-button { width: 44px !important; height: 44px !important; }
/* Extra Features groups inside the Tools sheet */
.gtbg-mp-more-h { font: 700 12px/1 system-ui, sans-serif; letter-spacing: .12em; text-transform: uppercase; color: #c9a24b; padding: 14px 4px 8px; }
.gtbg-mp-more .gtbg-item { min-height: 48px; }
.gtbg-mp-more .gtbg-item-desc, .gtbg-mp-more .gtbg-group-why { font-size: 12px; color: #a9b1c4; }
/* >>> modal touch targets */
/* desktop-derived modals reused on the phone shell: 44 px targets (class hooks from the C-*-hook patches) */
html[data-layout="mobile"] .gtbg-modal-overlay button { min-width: 44px; min-height: 44px; }
html[data-layout="mobile"] .gtbg-wt-head button { min-height: 44px; padding: 0 14px !important; }
html[data-layout="mobile"] .gtbg-layers { top: calc(var(--gt-hdr) + var(--gt-tabs) + var(--gt-sat) + 8px) !important; right: max(10px, var(--gt-sar)) !important; padding: 6px 10px !important; }
html[data-layout="mobile"] .gtbg-layers button { min-width: 44px; min-height: 44px; font-size: 20px !important; }
html[data-layout="mobile"] .gtbg-layers span { font-size: 14px !important; }
/* <<< modal touch targets */
/* >>> layers checkbox */
/* Map Layers checkboxes: 44 px hit box, 24 px drawn box (native checkboxes cannot be enlarged without looking oversized) */
html[data-layout="mobile"] #root .gtbg-layers input[type="checkbox"] { -webkit-appearance: none; appearance: none; width: 44px; height: 44px; margin: 0; position: relative; flex: none; background: transparent; cursor: pointer; }
html[data-layout="mobile"] #root .gtbg-layers input[type="checkbox"]::before { content: ""; position: absolute; inset: 10px; border: 2px solid #8b6914; border-radius: 4px; background: rgba(255,255,255,.05); }
html[data-layout="mobile"] #root .gtbg-layers input[type="checkbox"]:checked::before { background: #c8a84a; border-color: #c8a84a; }
html[data-layout="mobile"] #root .gtbg-layers input[type="checkbox"]:checked::after { content: ""; position: absolute; left: 17px; top: 12px; width: 6px; height: 12px; border: solid #12121e; border-width: 0 2.5px 2.5px 0; transform: rotate(45deg); }
html[data-layout="mobile"] #root .gtbg-layers input[type="checkbox"]:focus-visible { outline: 2px solid #e8d5a3; outline-offset: -2px; border-radius: 6px; }
/* <<< layers checkbox */
/* >>> attribution */
/* compact attribution: keep the 44 px button from covering the credit text once expanded */
.mapboxgl-ctrl-attrib.mapboxgl-compact-show { padding: 0 48px 0 10px !important; min-height: 44px; display: flex; align-items: center; border-radius: 22px; }
.mapboxgl-ctrl-attrib.mapboxgl-compact-show .mapboxgl-ctrl-attrib-inner { line-height: 1.3; }
.mapboxgl-ctrl-attrib.mapboxgl-compact .mapboxgl-ctrl-attrib-button { top: 0; right: 0; }
/* <<< attribution */
/* >>> popup priority */
/* a selected unit's popup and the story/event cards share the dock anchor: the popup wins, the cards return when it is closed */
html[data-layout="mobile"] .gtbg-m-root:has(> .gtbg-m-popup) .gtbg-mp-story { visibility: hidden; pointer-events: none; }
/* <<< popup priority */
/* >>> layers fit */
/* Map Layers: 7 rows x 44 px must not run under the dock or off a landscape screen: cap the height, scroll inside */
html[data-layout="mobile"] .gtbg-layers { max-height: calc(100dvh - var(--gt-hdr) - var(--gt-tabs) - var(--gt-sat) - 16px - var(--gt-dock) - var(--gt-sab)); overflow-y: auto; overscroll-behavior: contain; box-sizing: border-box; }
/* <<< layers fit */
/* >>> roster full screen */
/* Unit Roster: full screen on the phone shell (its inline style is a desktop side column: 560 px wide, bottom 110 px) */
html[data-layout="mobile"] .gtbg-roster { top: var(--gt-sat) !important; left: 0 !important; right: 0 !important; bottom: 0 !important; width: auto !important; }
/* <<< roster full screen */
/* >>> story stack */
/* D-04: one story/event card expanded, the other collapsed to a 44 px chip (gtStk controller + class hooks in the bundle); the stack never exceeds two thirds of the map zone, so it cannot reach the day tabs or cover the whole map */
.gtbg-mp-story > .gtbg-card[data-collapsed] { display: flex !important; flex-direction: row !important; align-items: center; min-height: 44px; max-height: 44px !important; overflow: hidden !important; padding: 0 !important; cursor: pointer; }
.gtbg-mp-story > .gtbg-card[data-collapsed] > * { display: none !important; }
.gtbg-mp-story > .gtbg-card[data-collapsed]::before { content: attr(data-chip); flex: 1 1 auto; min-width: 0; padding-left: 14px; font: 600 13px/44px system-ui, -apple-system, sans-serif; color: #e8d5a3; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.gtbg-mp-story > .gtbg-card[data-collapsed]::after { content: "\25B4"; flex: none; width: 44px; height: 44px; font: 16px/44px system-ui, sans-serif; text-align: center; color: #c8a84a; }
.gtbg-mp-story > .gtbg-card:only-child { max-height: calc(var(--gt-maph) * .58) !important; }
.gtbg-card-story [role="group"] { min-height: 44px; }
.gtbg-card-story [style*="border-radius: 50%"][style*="cursor: pointer"] { box-sizing: content-box; padding: 19px; background-clip: content-box !important; flex: none; }
@media (max-height: 740px) { .gtbg-card-story > :last-child { display: none; } }
/* <<< story stack */
/* >>> panel targets */
/* D-06: touch targets inside the re-homed desktop panels (Search rows and quick links, Follow Ancestor input, Filter range) */
.gtbg-mp-top [style*="cursor: pointer"] { min-height: 44px; box-sizing: border-box; align-items: center; }
.gtbg-m-root input:not([type="checkbox"]):not([type="radio"]):not([type="range"]) { min-height: 44px; box-sizing: border-box; }
.gtbg-m-root input[type="range"] { box-sizing: border-box; height: 44px; margin: 0; padding: 0; }
/* <<< panel targets */
/* >>> modal header */
/* D-03: Help / Bookmarks: the header (tabs + close) stays on screen while the content scrolls; the panel fits the dynamic viewport; phone tabs are tighter */
.gtbg-modal-overlay > div > div:first-child { position: sticky; top: 0; z-index: 3; background: inherit; }
html[data-layout="mobile"] .gtbg-modal-overlay > div { max-height: calc(100dvh - 32px) !important; overscroll-behavior: contain; }
html[data-layout="mobile"] .gtbg-modal-overlay > div > div:first-child button { padding-left: 10px; padding-right: 10px; }
/* <<< modal header */
/* phone landscape: give the map its height back */
@media (orientation: landscape) and (max-height: 480px) {
  :root { --gt-hdr: 48px; --gt-tabs: 0px; --gt-dock: 60px; }
  /* D-07: compact day control: the three day tabs sit in the top bar (centred, 44 px targets) instead of vanishing */
  html[data-layout="mobile"] .gtbg-m-days { top: var(--gt-sat) !important; left: 50% !important; right: auto !important; width: auto !important; height: var(--gt-hdr); transform: translateX(-50%); border-bottom: 0 !important; align-items: center; gap: 4px; z-index: 210 !important; }
  html[data-layout="mobile"] .gtbg-m-days button { flex: 0 0 auto !important; min-width: 64px; min-height: 44px !important; padding: 0 12px !important; border-radius: 8px !important; }
  html[data-layout="mobile"] .gtbg-m-dock { flex-direction: row !important; align-items: center !important; border-top-width: 1px !important; }
  html[data-layout="mobile"] .gtbg-m-scrub { flex: 1 1 auto !important; order: 2; margin: 0 12px; border: 0 !important; background: rgba(255,255,255,.08) !important; border-radius: 22px; height: 44px !important; }
  html[data-layout="mobile"] .gtbg-m-play { order: 1; padding: 0 0 0 12px !important; gap: 8px !important; }
  html[data-layout="mobile"] .gtbg-m-play > button { width: 44px !important; height: 44px !important; min-height: 44px !important; padding: 0 !important; font-size: 22px !important; }
  html[data-layout="mobile"] .gtbg-m-play > button:nth-child(2) { width: 48px !important; height: 48px !important; }
  /* D-07: the tick label and the minimap come back (label next to the speed button, minimap beside the legend) */
  html[data-layout="mobile"] .gtbg-m-play > div { display: block !important; flex: none; box-sizing: content-box; min-width: 88px; padding: 0 4px; text-align: center; font-size: 12px !important; line-height: 1.2; white-space: nowrap; }
  html[data-layout="mobile"] .gtbg-m-legend { left: max(10px, var(--gt-sal)) !important; }
  html[data-layout="mobile"] .gtbg-m-mini { left: calc(max(10px, var(--gt-sal)) + 98px) !important; right: auto !important; }
  html[data-layout="mobile"] .gtbg-m-toolspanel { max-width: min(440px, 50vw) !important; margin-left: auto; border-radius: 14px 0 0 0 !important; height: 100dvh !important; max-height: 100dvh !important; box-sizing: border-box; padding-right: var(--gt-sar); }
  .gtbg-mp-story { top: calc(var(--gt-hdr) + var(--gt-sat) + 8px); max-height: none; bottom: calc(var(--gt-dock) + var(--gt-sab) + 8px); left: auto; width: min(420px, 52vw); }
  .gtbg-mp-toast { right: auto; width: min(420px, 50vw); }
  .gtbg-mp-story { flex-direction: column; }
  .gtbg-mp-story > div { max-height: calc(var(--gt-maph) - 16px - 52px) !important; overflow-y: auto; }
  .gtbg-mp-story > .gtbg-card:only-child { max-height: calc(var(--gt-maph) - 16px) !important; }
  .gtbg-mp-story > div:first-child { order: 2; }
}

